sealed interface Either<L, R> permits Left, Right {}

record Left<L, R>(L reason) implements Either<L, R> {}
record Right<L, R>(R value) implements Either<L, R> {}

static String describe(Either<String, Integer> outcome) {
    return switch (outcome) {                       // exhaustive: no default arm (Java 21)
        case Left<String, Integer> l  -> "failed: " + l.reason();
        case Right<String, Integer> r -> "ok: " + r.value();
    };
}

