static String describe(Either<String, Integer> outcome) {
    if (outcome instanceof Left<String, Integer> l)  return "failed: " + l.reason();
    if (outcome instanceof Right<String, Integer> r) return "ok: " + r.value();
    throw new IllegalStateException("unreachable: " + outcome);
}

